              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-slate-600 mb-1">{isGu ? 'સરકારી ફી (₹)' : 'Govt Fee (₹)'}</label>
                  <input
                    type="number"
                    value={newGovtFee}
                    onChange={(e) => setNewGovtFee(Number(e.target.value))}
