                <div>
                  <label className="block text-slate-600 mb-1">{isGu ? 'CSC ચાર્જ (₹)' : 'CSC Commission (₹)'}</label>
                  <input
                    type="number"
                    value={newCscCharge}
                    onChange={(e) => setNewCscCharge(Number(e.target.value))}
                    className="w-full text-xs px-2 py-1.5 border border-slate-300 rounded-lg font-mono"
                  />
                </div>
              </div>

              <div>
                <label className="block text-slate-600 mb-1">
                  {isGu ? 'જરૂરી કાગળો (અલ્પવિરામથી અલગ કરો)' : 'Required Documents (comma separated)'}
                </label>
                <input
                  type="text"
                  value={newDocs}
                  onChange={(e) => setNewDocs(e.target.value)}
                  className="w-full text-xs px-3 py-2 border border-slate-300 rounded-lg"
                />
              </div>

              <div className="pt-2 flex justify-end gap-2 border-t border-slate-200">
                <button
                  type="button"
                  onClick={() => setIsAddModalOpen(false)}
                  className="px-3 py-1.5 text-xs text-slate-600 font-semibold"
                >
                  {isGu ? 'રદ કરો' : 'Cancel'}
                </button>
                <button
                  type="submit"
                  className="px-4 py-1.5 bg-slate-900 text-white font-semibold text-xs rounded-lg hover:bg-slate-800"
                >
                  {isGu ? 'સેવા ઉમેરો' : 'Add Service'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

src/components/admin/CustomerDirectory.t:
import React, { useState } from 'react';
import { useCSC } from '../../context/CSCContext';
import { Users, Search, Phone, MessageSquare, Plus, FileText } from 'lucide-react';
import { CSCApplication } from '../../types/csc';

interface CustomerDirectoryProps {
  onSelectCustomerForApp: (customer: { name: string; mobile: string; village: string; father: string }) => void;
}

export const CustomerDirectory: React.FC<CustomerDirectoryProps> = ({ onSelectCustomerForApp }) => {
  const { applications, language, centerSettings } = useCSC();
  const isGu = language === 'gu';

  const [search, setSearch] = useState('');

  // Group applications by mobile number to build customer records
  const customerMap: Record<string, {
    name: string;
    mobile: string;
    father: string;
    village: string;
    taluka: string;
    apps: CSCApplication[];
    totalPaid: number;
    lastActive: string;
  }> = {};

  applications.forEach((app) => {
    const key = app.mobile.replace(/\D/g, '');
    if (!customerMap[key]) {
      customerMap[key] = {
        name: app.customerName,
        mobile: app.mobile,
        father: app.fatherOrHusbandName || '',
        village: app.address.village,
        taluka: app.address.taluka,
        apps: [],
        totalPaid: 0,
        lastActive: app.submittedDate,
      };
    }
    customerMap[key].apps.push(app);
    if (app.paymentStatus === 'paid') {
      customerMap[key].totalPaid += app.amount;
    }
  });

  const customerList = Object.values(customerMap).filter((c) => {
    const q = search.toLowerCase().trim();
    return (
      !q ||
      c.name.toLowerCase().includes(q) ||
      c.mobile.includes(q) ||
      c.village.toLowerCase().includes(q)
    );
  });

  return (
    <div className="bg-white rounded-xl border border-slate-200 p-6 shadow-xs space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-4 border-b border-slate-200">
        <div>
          <h3 className="text-lg font-bold text-slate-900 flex items-center gap-2">
            <Users className="w-5 h-5 text-indigo-600" />
            <span>{isGu ? 'ગ્રાહકોની યાદી અને સંપર્ક ડેટાબેઝ' : 'Customer Directory & CRM'}</span>
          </h3>
          <p className="text-xs text-slate-500 mt-0.5">
            {isGu
              ? `કુલ ${customerList.length} નાગરિકો નોંધાયેલા છે. તેમના તમામ કેસ હિસ્ટ્રી અને સંપર્ક અહીં ઉપલબ્ધ છે.`
              : `${customerList.length} registered citizens with full service history`}
          </p>
        </div>

        <div className="relative w-full sm:w-72">
          <input
            type="text"
            placeholder={isGu ? 'નામ, મોબાઇલ અથવા ગામથી શોધો...' : 'Search by name, phone or village...'}
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full text-xs px-3 pl-9 py-2 border border-slate-300 rounded-lg focus:outline-hidden focus:ring-2 focus:ring-slate-900"
          />
          <Search className="w-4 h-4 text-slate-400 absolute left-3 top-2.5" />
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left border-collapse text-xs">
          <thead>
            <tr className="border-b border-slate-200 text-slate-500 font-semibold uppercase tracking-wider text-[11px]">
              <th className="py-2.5 px-3">ગ્રાહકનું પૂરું નામ</th>
              <th className="py-2.5 px-3">મોબાઇલ નંબર</th>
              <th className="py-2.5 px-3">ગામ / સરનામું</th>
              <th className="py-2.5 px-3 text-center">કુલ અરજીઓ</th>
              <th className="py-2.5 px-3 text-right">ચૂકવેલ ફી (₹)</th>
              <th className="py-2.5 px-3 text-right">સંપર્ક / ક્રિયા</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100 font-medium text-slate-700">
            {customerList.map((c) => (
              <tr key={c.mobile} className="hover:bg-slate-50 transition-colors">
                <td className="py-3 px-3">
                  <div className="font-bold text-slate-900">{c.name}</div>
                  {c.father && (
                    <div className="text-[11px] text-slate-400">પિતા: {c.father}</div>
                  )}
                </td>

                <td className="py-3 px-3 font-mono font-semibold text-slate-800">
                  {c.mobile}
                </td>

                <td className="py-3 px-3">
                  <span>{c.village}, {c.taluka}</span>
                </td>

                <td className="py-3 px-3 text-center">
                  <span className="font-mono font-bold bg-slate-100 text-slate-800 px-2 py-0.5 rounded text-[11px]">
                    {c.apps.length}
                  </span>
                </td>

                <td className="py-3 px-3 text-right font-mono font-bold text-emerald-700">
                  ₹{c.totalPaid}
                </td>

                <td className="py-3 px-3 text-right">
                  <div className="flex items-center justify-end gap-1.5">
                    {/* Call shortcut */}
                    <a
                      href={`tel:${c.mobile.replace(/\D/g, '')}`}
                      className="p-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded transition-colors"
                      title="Call Citizen"
                    >
                      <Phone className="w-3.5 h-3.5" />
                    </a>

                    {/* WhatsApp shortcut */}
                    <a
                      href={`https://wa.me/91${c.mobile.replace(/\D/g, '')}?text=${encodeURIComponent(`નમસ્તે ${c.name}જી, આપના CSC કેન્દ્ર સંબંધિત કામકાજ માટે સંપર્ક કર્યો છે.`)}`}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="p-1.5 bg-emerald-50 hover:bg-emerald-100 text-emerald-700 rounded transition-colors"
                      title="WhatsApp Chat"
                    >
                      <MessageSquare className="w-3.5 h-3.5" />
                    </a>

                    {/* New application shortcut */}
                    <button
                      onClick={() => onSelectCustomerForApp({
                        name: c.name,
                        mobile: c.mobile,
                        village: c.village,
                        father: c.father,
                      })}
                      className="flex items-center gap-1 px-2 py-1 bg-slate-900 hover:bg-slate-800 text-white rounded text-[11px] font-semibold transition-colors cursor-pointer"
                      title="Create Application"
                    >
                      <Plus className="w-3 h-3 text-amber-400" />
                      <span>{isGu ? 'નવી અરજી' : 'New App'}</span>
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {customerList.length === 0 && (
        <div className="text-center py-8 text-slate-500 text-xs">
          {isGu ? 'કોઈ ગ્રાહક મળ્યા નથી.' : 'No customer records found.'}
        </div>
      )}
    </div>
  );
};

src/components/admin/CenterSettingsModal:
import React, { useState } from 'react';
import { useCSC } from '../../context/CSCContext';
import { Settings, X, Save, AlertCircle } from 'lucide-react';
import { CSCCenterSettings } from '../../types/csc';

interface CenterSettingsModalProps {
  onClose: () => void;
}

export const CenterSettingsModal: React.FC<CenterSettingsModalProps> = ({ onClose }) => {
  const { centerSettings, updateCenterSettings, language, resetDataToDefaults, adminPin, changeAdminPin } = useCSC();
  const isGu = language === 'gu';

  const [form, setForm] = useState<CSCCenterSettings>({ ...centerSettings });
  const [formPin, setFormPin] = useState(adminPin);
  const [success, setSuccess] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    updateCenterSettings(form);
    if (formPin && formPin !== adminPin) {
      changeAdminPin(adminPin, formPin);
    }
    setSuccess(true);
    setTimeout(() => {
      setSuccess(false);
      onClose();
    }, 800);
  };

  const handleReset = () => {
    if (confirm(isGu ? 'શું તમે ડિફોલ્ટ સેમ્પલ ડેટા રીસેટ કરવા માંગો છો?' : 'Reset to factory sample data?')) {
      resetDataToDefaults();
      onClose();
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs overflow-y-auto">
      <div className="bg-white rounded-xl shadow-2xl max-w-xl w-full border border-slate-200 overflow-hidden my-6">
        <div className="bg-slate-900 text-white px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Settings className="w-5 h-5 text-amber-400" />
            <h3 className="font-bold text-base">
              {isGu ? 'કેન્દ્ર સેટિંગ્સ અને પ્રોફાઇલ' : 'Center Profile & Settings'}
            </h3>
          </div>
          <button onClick={onClose} className="p-1.5 text-slate-400 hover:text-white rounded-lg hover:bg-slate-800">
            <X className="w-5 h-5" />
          </button>
        </div>

        {success && (
          <div className="bg-emerald-600 text-white text-xs py-2 px-4 text-center font-medium">
            ✓ {isGu ? 'સેટિંગ્સ સફળતાપૂર્વક સાચવવામાં આવી!' : 'Settings updated successfully!'}
          </div>
        )}

        <form onSubmit={handleSubmit} className="p-6 space-y-4 text-xs">
          <div>
            <label className="block font-semibold text-slate-700 mb-1">
              {isGu ? 'કેન્દ્રનું નામ (ગુજરાતી)' : 'Center Name (Gujarati)'}
            </label>
            <input
              type="text"
              required
              value={form.centerName}
              onChange={(e) => setForm({ ...form, centerName: e.target.value })}
              className="w-full text-xs px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-slate-900"
            />
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div>
              <label className="block font-semibold text-slate-700 mb-1">
                {isGu ? 'સંચાલકનું નામ (VLE Operator)' : 'VLE Operator Name'}
              </label>
              <input
                type="text"
                required
                value={form.vleName}
                onChange={(e) => setForm({ ...form, vleName: e.target.value })}
                className="w-full text-xs px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-slate-900"
              />
            </div>
            <div>
              <label className="block font-semibold text-slate-700 mb-1">
                {isGu ? 'મોબાઇલ નંબર' : 'Center Mobile Number'}
              </label>
              <input
                type="tel"
                required
                value={form.mobile}
                onChange={(e) => setForm({ ...form, mobile: e.target.value })}
                className="w-full text-xs font-mono px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-slate-900"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block font-semibold text-slate-700 mb-1">VLE ID</label>
              <input
                type="text"
                value={form.vleId}
                onChange={(e) => setForm({ ...form, vleId: e.target.value })}
                className="w-full text-xs font-mono px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-slate-900"
              />
            </div>
            <div>
              <label className="block font-semibold text-slate-700 mb-1">CSC E-Gov ID</label>
              <input
                type="text"
                value={form.cscId}
                onChange={(e) => setForm({ ...form, cscId: e.target.value })}
                className="w-full text-xs font-mono px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-slate-900"
              />
            </div>
          </div>

          <div>
            <label className="block font-semibold text-slate-700 mb-1">
              {isGu ? 'કેન્દ્રનું પૂરું સરનામું (રસીદ પર પ્રિન્ટ થશે)' : 'Center Address'}
            </label>
            <input
              type="text"
              value={form.addressGu}
              onChange={(e) => setForm({ ...form, addressGu: e.target.value })}
              className="w-full text-xs px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-slate-900"
            />
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div>
              <label className="block font-semibold text-slate-700 mb-1">
                {isGu ? 'કામકાજના કલાકો' : 'Working Hours'}
              </label>
              <input
                type="text"
                value={form.workingHours}
                onChange={(e) => setForm({ ...form, workingHours: e.target.value })}
                className="w-full text-xs px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-slate-900"
              />
            </div>
            <div>
              <label className="block font-semibold text-slate-700 mb-1">
                {isGu ? 'UPI ID (QR કોડ પેમેન્ટ માટે)' : 'UPI ID for QR'}
              </label>
              <input
                type="text"
                value={form.upiId}
                onChange={(e) => setForm({ ...form, upiId: e.target.value })}
                className="w-full text-xs font-mono px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-slate-900"
              />
            </div>
          </div>

          {/* Announcement Banner Setup */}
          <div className="p-3 bg-amber-50/70 border border-amber-200 rounded-lg space-y-2">
            <div className="flex items-center justify-between">
              <label className="font-bold text-amber-950 flex items-center gap-1.5">
                <span>{isGu ? 'ટોચની સૂચના પટ્ટી (Top Notice Banner)' : 'Notice Banner'}</span>
              </label>
              <label className="flex items-center gap-1.5 cursor-pointer">
                <input
                  type="checkbox"
                  checked={form.isAnnouncementActive}
                  onChange={(e) => setForm({ ...form, isAnnouncementActive: e.target.checked })}
                  className="w-4 h-4 rounded text-amber-600 focus:ring-amber-500"
                />
                <span className="font-semibold text-amber-900">{isGu ? 'દર્શાવો' : 'Active'}</span>
              </label>
            </div>
            <textarea
              rows={2}
              value={form.announcementTextGu}
              onChange={(e) => setForm({ ...form, announcementTextGu: e.target.value })}
              className="w-full text-xs px-3 py-2 border border-amber-300 rounded-lg bg-white focus:ring-2 focus:ring-amber-600"
            />
          </div>

          {/* Operator Security PIN change */}
          <div className="p-3 bg-slate-100 rounded-lg border border-slate-200">
            <label className="block font-bold text-slate-800 mb-1">
              {isGu ? 'સંચાલક લોગિન સિક્યોરિટી પિન (Security PIN)' : 'Operator Security PIN'}
            </label>
            <div className="flex items-center gap-2">
              <input
                type="text"
                maxLength={6}
                value={formPin}
                onChange={(e) => setFormPin(e.target.value.replace(/\D/g, ''))}
                className="w-32 text-xs font-mono font-bold px-3 py-1.5 border border-slate-300 rounded bg-white text-center"
              />
              <span className="text-[11px] text-slate-500">
                {isGu ? 'એડમિન પેનલમાં પ્રવેશવા માટે આ પિન જરૂરી રહેશે.' : 'Required for operator login.'}
              </span>
            </div>
          </div>

          {/* Buttons */}
          <div className="pt-2 flex items-center justify-between border-t border-slate-200">
            <button
              type="button"
              onClick={handleReset}
              className="text-xs text-rose-600 hover:text-rose-800 font-semibold"
            >
              {isGu ? 'ડિફોલ્ટ રીસેટ' : 'Reset Defaults'}
            </button>

            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={onClose}
                className="px-3 py-1.5 text-xs text-slate-600 font-semibold"
              >
                {isGu ? 'રદ કરો' : 'Cancel'}
              </button>
              <button
                type="submit"
                className="flex items-center gap-1.5 px-4 py-2 bg-slate-900 text-white font-semibold text-xs rounded-lg hover:bg-slate-800 transition-colors"
              >
                <Save className="w-4 h-4 text-amber-400" />
                <span>{isGu ? 'સાચવો' : 'Save'}</span>
              </button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
};
